DROP TABLE IF EXISTS `dwh_fact_penjualan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dwh_fact_penjualan` (
  `id_fact` int NOT NULL AUTO_INCREMENT,
  `id_waktu` int NOT NULL,
  `id_dim_produk` int NOT NULL,
  `id_dim_cabang` int NOT NULL,
  `id_penjualan` bigint NOT NULL,
  `metode_pembayaran` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `qty` int NOT NULL,
  `harga_jual` decimal(15,2) NOT NULL,
  `harga_modal` decimal(15,2) NOT NULL,
  `subtotal` decimal(15,2) NOT NULL,
  `profit` decimal(15,2) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id_fact`),
